-- The workspace records are generated by monitors.nix and shared with the shell.
local M = {}

local function on_focused_monitor()
    local monitor = hl.get_active_monitor()
    local result = {}
    if not monitor then return result, nil end
    for _, workspace in ipairs(workspaces) do
        if workspace.monitor == monitor.name then
            result[#result + 1] = workspace
        end
    end
    return result, monitor
end

function M.focus(label, move)
    local entries = on_focused_monitor()
    for _, workspace in ipairs(entries) do
        if workspace.label == label then
            if move then
                hl.dispatch(hl.dsp.window.move({ workspace = workspace.id }))
            else
                hl.dispatch(hl.dsp.focus({ workspace = workspace.id }))
            end
            return
        end
    end
end

function M.cycle(delta)
    local entries, monitor = on_focused_monitor()
    if #entries == 0 then return end
    local active = monitor.active_workspace
    local index = 1
    for i, workspace in ipairs(entries) do
        if active and workspace.id == active.id then index = i end
    end
    local next_entry = entries[(index - 1 + delta) % #entries + 1]
    hl.dispatch(hl.dsp.focus({ workspace = next_entry.id }))
end

return M
